// Presentation of fixed editorial content only. No device or baby responses are collected.
export function audioAvailabilityCopy(availability,language){
 if(availability.status==='api-unavailable')return {status:'api-unavailable',title:'API de voz no disponible',detail:'Este navegador no ofrece la síntesis necesaria. Puedes seguir con tu propia voz; no activamos servicios externos.'};
 if(availability.available)return {status:'voice-detected',title:'Voz compatible detectada',detail:`Voz sintética local declarada por el navegador: ${availability.voice.lang}${availability.voice.name?' · '+availability.voice.name:''}. Detectarla no verifica su pronunciación ni su calidad; requiere escucha humana.`};
 return {status:'not-detected',title:'Ninguna voz compatible detectada por ahora',detail:`No hay una voz local compatible disponible ahora para ${language.name}${language.voiceLocales?' ('+language.voiceLocales.join(', ')+')':''}. Revisa de nuevo si aparecen voces más tarde o sigue con tu propia voz. No sustituimos el idioma ni usamos un servicio externo.`};
}
export function routineGroups(lines){return {invitation:lines.map((line,index)=>({line,index})).filter(x=>!x.line.conditional),response:lines.map((line,index)=>({line,index})).filter(x=>x.line.conditional)};}
export const deviceTestMarkup=()=>`<details class="early-device-test"><summary>Prueba en tu dispositivo · solo para adultos</summary><p>Haz esta comprobación sin el bebé presente. No es una actividad para evaluar al bebé ni una validación de pronunciación.</p><ol><li>Anota por tu cuenta dispositivo, sistema, navegador e idioma. La app no recoge estas notas.</li><li>Abrir, iniciar y retomar no deben reproducir audio. Con volumen suave, pulsa Escuchar una vez y comprueba que oyes una sola frase.</li><li>Prueba Detener, cambiar de idioma y volver al inicio mientras suena. No debe quedar audio superpuesto ni reiniciarse solo.</li><li>Cambia de pestaña y prueba bloqueo/desbloqueo. Al volver, no debe empezar a hablar. No prometemos reproducción en segundo plano.</li><li>Con VoiceOver o TalkBack, comprueba nombres, foco y avisos; anota si el lector y la referencia hablada se solapan. Es una hipótesis pendiente de prueba real.</li></ol><p>Comparte solo configuración y resultado si quieres dar feedback. Sin grabaciones ni datos personales de menores. Si el audio continúa al pedir detenerlo, cierra la página y comunícalo antes de volver a reproducir.</p></details>`;
export const audioCheckMarkup=()=>`<section class="early-audio-check" aria-labelledby="early-audio-check-title"><p class="eyebrow">APOYO HABLADO · OPCIONAL</p><h2 id="early-audio-check-title" tabindex="-1" aria-describedby="early-voice"></h2><p id="early-voice"></p><button type="button" class="action secondary" id="early-voices-refresh">Revisar voces disponibles</button></section>`;
